inline int llfsm_check(int value, int lower, int upper, const char *name)
{
    if (value < lower || value > upper) {
        std::cout.flush();
        std::cerr << "range violation " << name << '\n';
        std::exit(2);
    }
    return value;
}

inline std::size_t llfsm_index(int index, int size, const char *name)
{
    return static_cast<std::size_t>(llfsm_check(index, 0, size - 1, name));
}

inline void llfsm_print_bool(bool value)
{
    std::cout << (value ? "true" : "false");
}

inline void llfsm_print_int(int value)
{
    std::cout << value;
}

enum class Side { left, right };

inline std::string_view llfsm_name(Side value)
{
    constexpr std::array<std::string_view, 2> names{{ "left", "right" }};
    return names[static_cast<std::size_t>(value)];
}

inline void llfsm_print_Side(Side value)
{
    std::cout << llfsm_name(value);
}

inline bool llfsm_parse_Side(const std::string &text, Side &out)
{
    for (std::size_t k = 0; k < 2; k++) {
        if (text == llfsm_name(static_cast<Side>(k))) {
            out = static_cast<Side>(k);
            return true;
        }
    }
    return false;
}

using Count = int;

inline bool llfsm_parse_Count(const std::string &text, Count &out)
{
    char *end = nullptr;
    errno = 0;
    long value = std::strtol(text.c_str(), &end, 10);
    if (end == text.c_str() || *end != '\0' || errno != 0 || value < 0 || value > 9) {
        return false;
    }
    out = static_cast<int>(value);
    return true;
}

class llfsm_Arrangement;

enum class Relay_State { Waiting, Holding, Passing };

inline std::string_view llfsm_name(Relay_State state)
{
    constexpr std::array<std::string_view, 3> names{{ "Waiting", "Holding", "Passing" }};
    return names[static_cast<std::size_t>(state)];
}

inline bool llfsm_is_accepting(Relay_State state)
{
    constexpr std::array<bool, 3> flags{{ false, false, false }};
    return flags[static_cast<std::size_t>(state)];
}

inline bool llfsm_is_pass_through(Relay_State state)
{
    constexpr std::array<bool, 3> flags{{ false, false, true }};
    return flags[static_cast<std::size_t>(state)];
}

struct Relay_Machine {
    Relay_State llfsm_pc = Relay_State::Waiting;
    bool llfsm_entered = true;
    Side me{};
    Count passes{};

    void llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement);
};

class llfsm_Arrangement {
public:
    Side turn{};
    Relay_Machine llfsm_instance_leftHand;
    Relay_Machine llfsm_instance_rightHand;

    llfsm_Arrangement()
    {
        turn = Side::left;
        llfsm_instance_leftHand.me = Side::left;
        llfsm_instance_leftHand.passes = 0;
        llfsm_instance_rightHand.me = Side::right;
        llfsm_instance_rightHand.passes = 0;
    }

    bool llfsm_set_external(const std::string &key, bool indexed, int index, const std::string &value)
    {
        (void)key;
        (void)indexed;
        (void)index;
        (void)value;
        return false;
    }

    bool llfsm_apply_assignment(std::string token)
    {
        std::size_t equals = token.find('=');
        if (equals == std::string::npos) {
            return false;
        }
        std::string value = token.substr(equals + 1);
        token.erase(equals);
        bool indexed = false;
        int index = 0;
        std::size_t bracket = token.find('\x5b');
        if (bracket != std::string::npos) {
            const std::string position = token.substr(bracket + 1);
            std::size_t first = (!position.empty() && (position[0] == '+' || position[0] == '-')) ? 1 : 0;
            if (position.size() < first + 2 || position.back() != '\x5d'
                || position.find_first_not_of("0123456789", first) != position.size() - 1) {
                return false;
            }
            errno = 0;
            long parsed = std::strtol(position.c_str(), nullptr, 10);
            if (errno != 0 || parsed < INT_MIN || parsed > INT_MAX) {
                return false;
            }
            index = static_cast<int>(parsed);
            indexed = true;
            token.erase(bracket);
        }
        return llfsm_set_external(token, indexed, index, value);
    }

    bool llfsm_apply_inputs(const std::vector<std::string> &lines, int round)
    {
        for (const std::string &line : lines) {
            std::istringstream fields(line);
            long when = 0;
            if (!(fields >> when) || when != round) {
                continue;
            }
            std::string token;
            while (fields >> token) {
                if (!llfsm_apply_assignment(token)) {
                    std::cerr << "invalid input " << token << '\n';
                    return false;
                }
            }
        }
        return true;
    }

    int llfsm_run(int maxRounds, const std::vector<std::string> &inputLines)
    {
        std::cout << "arrangement TurnTakingRelay\n";
        for (int round = 1; ; round++) {
            if (!llfsm_apply_inputs(inputLines, round)) {
                return 1;
            }
            llfsm_instance_leftHand.llfsm_ringlet(*this);
            std::cout << "R" << round << " leftHand " << llfsm_name(llfsm_instance_leftHand.llfsm_pc) << '\n';
            llfsm_instance_rightHand.llfsm_ringlet(*this);
            std::cout << "R" << round << " rightHand " << llfsm_name(llfsm_instance_rightHand.llfsm_pc) << '\n';
            if (llfsm_is_accepting(llfsm_instance_leftHand.llfsm_pc) && !llfsm_instance_leftHand.llfsm_entered && llfsm_is_accepting(llfsm_instance_rightHand.llfsm_pc) && !llfsm_instance_rightHand.llfsm_entered) {
                std::cout << "halt R" << round << '\n';
                break;
            }
            if (round == maxRounds) {
                break;
            }
        }
        return 0;
    }
};

void Relay_Machine::llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement)
{
    Side &turn = llfsm_arrangement.turn;
    (void)llfsm_arrangement;
    (void)turn;
    for (;;) {
        if (llfsm_entered) {
            llfsm_entered = false;
            switch (llfsm_pc) {
            case Relay_State::Holding:
                std::cout << "holding";
                std::cout << ' ';
                llfsm_print_Side(me);
                std::cout << ' ';
                llfsm_print_int(passes);
                std::cout << '\n';
                break;
            case Relay_State::Passing:
                turn = ((me == Side::left) ? Side::right : Side::left);
                passes = llfsm_check((passes + 1), 0, 9, "passes");
                break;
            default:
                break;
            }
        }
        bool llfsm_fired = true;
        switch (llfsm_pc) {
        case Relay_State::Waiting:
            if (turn == me) {
                llfsm_pc = Relay_State::Holding;
            } else {
                llfsm_fired = false;
            }
            break;
        case Relay_State::Holding:
            if (passes < 9) {
                llfsm_pc = Relay_State::Passing;
            } else {
                llfsm_fired = false;
            }
            break;
        case Relay_State::Passing:
            if (true) {
                llfsm_pc = Relay_State::Waiting;
            } else {
                llfsm_fired = false;
            }
            break;
        default:
            llfsm_fired = false;
            break;
        }
        if (!llfsm_fired) {
            return;
        }
        llfsm_entered = true;
        if (!llfsm_is_pass_through(llfsm_pc)) {
            return;
        }
    }
}

int main(int argc, char **argv)
{
    int maxRounds = argc > 1 ? std::atoi(argv[1]) : 20;
    std::vector<std::string> inputLines;
    if (argc > 2) {
        std::ifstream inputs(argv[2]);
        if (!inputs) {
            std::cerr << "cannot open " << argv[2] << '\n';
            return 1;
        }
        std::string line;
        while (std::getline(inputs, line)) {
            inputLines.push_back(line);
        }
    }
    llfsm_Arrangement arrangement;
    return arrangement.llfsm_run(maxRounds, inputLines);
}
